function paintColor(value){if(!value||value==='none'||value==='transparent')return [];if(value==='white')value='#ffffff';let v,op=1;if(value[0]==='#'){let h=value.slice(1);if(h.length===3)h=h.split('').map(c=>c+c).join('');v=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16));}else{v=value.match(/[\d.]+/g).map(Number);op=v.length>3?v[3]:1;}if(!op)return [];return [{type:'SOLID',color:{r:v[0]/255,g:v[1]/255,b:v[2]/255},opacity:op}];}
async function makeDesigns(){const available=await figma.listAvailableFontsAsync();const normalize=s=>s.toLowerCase().replace(/[\s_-]/g,'');const fonts={};for(const [weight,style] of [[400,'Regular'],[600,'SemiBold'],[700,'Bold']]){let match;for(const family of ['Be Vietnam Pro','Inter','Arial']){match=available.find(f=>f.fontName.family===family&&normalize(f.fontName.style)===normalize(style));if(match)break;}const face=match?match.fontName:{family:'Inter',style:'Regular'};await figma.loadFontAsync(face);fonts[weight]=face;}
 const built=[];let offsetX=Math.round(figma.viewport.center.x),top=Math.round(figma.viewport.center.y);try{const mobiles=designs.filter(d=>d.size==='mobile'),desktops=designs.filter(d=>d.size==='desktop');for(const row of [mobiles,desktops]){let x=offsetX,maxH=0;for(const design of row){const frame=figma.createFrame();built.push(frame);frame.name=design.title+' · '+(design.size==='mobile'?'Mobile':'Desktop');frame.resize(design.width,design.height);frame.x=x;frame.y=top;frame.fills=paintColor('#f5f6f2');frame.clipsContent=true;let area='',group=[];function groupSection(){if(group.length>1){const g=figma.group(group,frame);g.name=area;}group=[];}
 for(const it of design.items){if(it.group!==area){groupSection();area=it.group;}let node;if(it.type==='text'){node=figma.createText();const weight=it.bold>=700?700:it.bold>=550?600:400;node.fontName=fonts[weight];node.fontSize=it.font;node.letterSpacing={unit:'PIXELS',value:it.ls};node.textAutoResize='WIDTH_AND_HEIGHT';node.characters=it.txt;node.fills=paintColor(it.c);node.name=it.txt.slice(0,64);}else if(it.type==='icon'){node=figma.createNodeFromSvg(it.svg);node.name='Biểu tượng';}else if(it.type==='line'){node=figma.createRectangle();node.resize(1,Math.max(.01,it.h));node.fills=paintColor(it.c);node.name='Đường thời gian';}else{node=figma.createRectangle();node.resize(Math.max(.01,it.w),Math.max(.01,it.h));if(it.type==='photo'){const img=figma.createImage(figma.base64Decode(it.encoded));node.fills=[{type:'IMAGE',scaleMode:'FILL',imageHash:img.hash}];node.cornerRadius=design.size==='mobile'?18:22;node.name='Trạm sạc ban đêm';}else{node.fills=paintColor(it.c);node.cornerRadius=Math.max(0,Math.min(it.rad,it.w/2,it.h/2));if(it.stroke&&it.sw){node.strokes=paintColor(it.stroke);node.strokeWeight=it.sw;node.strokeAlign='INSIDE';}node.name='Nền và viền';}}
 frame.appendChild(node);node.x=it.x;node.y=it.type==='text'?it.y-it.asc:it.y;group.push(node);}groupSection();x+=design.width+100;maxH=Math.max(maxH,design.height);}top+=maxH+140;}
 figma.currentPage.selection=built;figma.viewport.scrollAndZoomIntoView(built.slice(0,1));figma.closePlugin('Đã tạo 12 khung ChargePilot.');}catch(e){for(const frame of built)if(!frame.removed)frame.remove();throw e;}}
makeDesigns().catch(e=>figma.closePlugin('Chưa tạo được khung: '+String(e)));
